<script setup>
import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import api from '../../../services/api';import FormErrors from '../../../components/ui/FormErrors.vue';import PlanCard from '../../../components/admin/plans/PlanCard.vue';
import AppIcon from '../../../components/ui/AppIcon.vue';
const route=useRoute();
const plans=ref([]),loading=ref(true),error=ref(null);const stats=computed(()=>({total:plans.value.length,active:plans.value.filter(p=>p.status==='active').length,subscriptions:plans.value.reduce((n,p)=>n+(p.subscriptions_count||0),0),trials:plans.value.reduce((n,p)=>n+(p.trial_subscriptions_count||0),0)}));async function load(){plans.value=(await api.get('/v1/platform/plans')).data.data}async function remove(plan){if(!window.confirm(`Delete ${plan.name}? This action cannot be undone.`))return;error.value=null;try{await api.delete('/v1/platform/plans/'+plan.id);await load()}catch(e){error.value=e}}async function toggleStatus(plan){error.value=null;try{await api.put('/v1/platform/plans/'+plan.id,{...plan,status:plan.status==='active'?'inactive':'active'});await load()}catch(e){error.value=e}}onMounted(async()=>{try{await load()}catch(e){error.value=e}finally{loading.value=false}})
</script>
<template><div><header class="page-header"><div><p class="eyebrow">Platform administration</p><h1>Subscription Plans</h1><p>Create and manage pricing plans, limits and features available to clinics.</p></div><RouterLink class="btn" :to="{name:'admin.plans.create'}">+ Add New Plan</RouterLink></header><p v-if="route.query.deleted" role="status" class="mb-5 rounded-xl bg-emerald-50 p-4 text-emerald-800">Subscription plan deleted successfully.</p><FormErrors :error="error"/><p v-if="loading" class="loading-state">Loading plans...</p><template v-else><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><article class="stat-card stat-mint"><span class="stat-icon"><AppIcon name="plans" :size="28"/></span><div><p>Total Plans</p><strong>{{stats.total}}</strong></div></article><article class="stat-card stat-blue"><span class="stat-icon text-blue-600"><AppIcon name="check" :size="28"/></span><div><p>Active Plans</p><strong>{{stats.active}}</strong></div></article><article class="stat-card stat-amber"><span class="stat-icon text-amber-600"><AppIcon name="subscriptions" :size="28"/></span><div><p>Total Subscriptions</p><strong>{{stats.subscriptions}}</strong></div></article><article class="stat-card stat-violet"><span class="stat-icon text-violet-600"><AppIcon name="trial" :size="28"/></span><div><p>Trial Subscriptions</p><strong>{{stats.trials}}</strong></div></article></div><div class="mt-6 grid gap-5 md:grid-cols-2 xl:grid-cols-3"><PlanCard v-for="plan in plans" :key="plan.id" :plan="plan" @delete="remove" @status="toggleStatus"/></div><p v-if="!plans.length" class="empty-state admin-card mt-6">No subscription plans have been created.</p></template></div></template>
